"""
note.comのマガジンページから特定パターンの記事を抽出し、PDFとして保存するスクリプト

[主な機能]
- 特定のマガジンページから、タイトルに指定のキーワードが含まれる記事のURLを全て収集します。
- ページの「もっとみる」ボタンに完全対応するため、ユーザーが手動でボタンをクリックする半自動処理フローを採用しています。
- 収集した記事情報（学校名、各教科のURL, X投稿文）はJSONファイルに保存・再利用されます。
- 記事を読みやすいレイアウトのPDFとして保存します（広告除去、ヘッダーなし、フッターにページ番号）。
- PDFのファイル名は、記事のタイトルから自動的に生成されます。
- 一度生成したPDFは、次回以降の実行ではスキップされます。
- 記事ごとにX(Twitter)への投稿文を自動生成し、JSONファイルに保存します。

[処理フロー・使い方]
1. (初回のみ) 必要なライブラリをインストールします。
   pip install selenium webdriver-manager pykakasi

2. スクリプトを実行します。
   python create_pdf_reports.py

3. 実行したい処理を選択します。
   - `1`: note.comから最新の記事情報を収集・更新します（ブラウザ操作が必要です）。
   - `2`: 既存のJSON情報からPDFを生成します（全自動）。
   - `3`: 既存のJSON情報からX投稿を生成します（未生成のみ）。
   - `4`: 既存のJSON情報からX投稿を【強制的に再生成】します。
   - `5`: 全ての処理を順番に実行します（1→2→3）。

4. `1` または `5` を選択した場合、Chromeブラウザが起動します。
   マガジンページの「もっとみる」ボタンがなくなるまで手動でクリックし、
   ターミナルに戻ってEnterキーを押すと、処理が再開されます。

5. あとは、選択した処理が自動で完了します。

[設定可能な項目]
-MAGAZINE_URL:      対象のnoteマガジンページのURL
- JSON_OUTPUT_FILE:  収集した記事情報を保存するファイル名
- OUTPUT_DIR:        生成したPDFを保存するディレクトリ名
- HEADLESS_MODE:     手動操作のため、このスクリプトでは常に `False` に設定されています。
"""

import os
import json
import time
import re
import base64
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.chrome.options import Options
from selenium.webdriver.chrome.service import Service
from webdriver_manager.chrome import ChromeDriverManager
from selenium.common.exceptions import TimeoutException
from pykakasi import kakasi

def generate_x_post(driver, school_name, subject, url):
    """記事ページから「意味のある」抜粋を取得し、Xの投稿文を生成する"""

    # noteの本文が格納されている可能性のあるセレクタリスト
    selectors = ["div.o-noteContentText", "div.note-common-styles__textnote-body"]
    article_text = ""
    for selector in selectors:
        try:
            content_element = driver.find_element(By.CSS_SELECTOR, selector)
            article_text = content_element.text.strip()
            if article_text:
                break
        except Exception:
            continue

    if not article_text:
        print(f"    - 警告: 記事本文の取得に失敗しました。投稿文は定型文になります。")
        article_text = "出題傾向や対策のポイントをまとめています。ぜひご活用ください！"

    # --- 新しい抜粋ロジック ---
    excerpt = ""
    # 抽出対象のセクションタイトル
    section_titles = [
        "2. 試験時間、問題数、問題用紙の構成",
        "3. 計算問題、文章問題（特殊算）、図形問題）の出題比率",
        "4. 頻繁に出題される算数的トピックや問題形式"
    ]

    # セクションの内容を抽出
    extracted_sections = []
    for title in section_titles:
        # 正規表現でセクションの内容を抽出（次のセクションタイトル or 記事の終わりまで）
        pattern = re.escape(title) + r"\s*\n(.*?)(?=\n\d+\.\s|\Z)"
        match = re.search(pattern, article_text, re.DOTALL)
        if match:
            content = match.group(1).strip()
            # 不要な改行やスペースを整理
            content = ' '.join(content.split())
            extracted_sections.append(content)

    if extracted_sections:
        excerpt = " ".join(extracted_sections)
    else:
        # セクションが見つからない場合は、既存のロジックにフォールバック
        teaser_keywords = ['ポイント', '攻略', '分析', '傾向', '対策', '秘訣', '鍵', '特徴', '出題', '構成']
        sentences = [s.strip() for s in article_text.replace('\n', ' ').split('。') if s]
        for sentence in sentences[1:]:
            if any(keyword in sentence for keyword in teaser_keywords) and len(sentence) > 20:
                excerpt = sentence + "。"
                break
        if not excerpt:
            if len(sentences) > 1:
                excerpt = sentences[1] + "。"
            elif sentences:
                excerpt = sentences[0] + "。"
            else:
                excerpt = "出題傾向や対策のポイントをまとめています。ぜひご活用ください！"
    # --- ロジック終了 ---

    headline = f"{school_name}過去問分析（2026版）より。"
    post_url = f"👉 {url}"

    # URLはt.coで23文字としてカウント
    url_len = 23

    # 見出し、URL、間のスペースなど、本文以外の長さを計算
    # フォーマット: <見出し>\n\n<本文>\n\n<URL>
    other_parts_len = len(headline) + 4 + len("👉 ") + url_len # 空行2つ分(4)

    # 本文に使える最大長
    max_body_len = 140 - other_parts_len

    if max_body_len < 10: # 本文スペースがほとんどない場合
        if len(headline) > 140 - (len("👉 ") + url_len + 2): # 空行1つ分(2)
            headline = headline[:140 - (len("👉 ") + url_len + 2) - 1] + "…"
        return f"{headline}\n\n{post_url}"

    # 本文（抜粋）を切り出す
    if len(excerpt) > max_body_len:
        body = excerpt[:max_body_len - 1] + "…"
    else:
        body = excerpt

    return f"{headline}\n\n{body}\n\n{post_url}"


# --- 設定 ---
MAGAZINE_URL = 'https://note.com/tanabe_2024/m/m79da93e4a818'
JSON_OUTPUT_FILE = 'note_reports.json'
OUTPUT_DIR = 'pdf_reports'
# このスクリプトでは、手動操作のためヘッドレスモードは必ず無効にする
HEADLESS_MODE = False
PAGE_LOAD_TIMEOUT = 20

# 科目のマッピング
SUBJECT_MAP = {
    "国語": "japanese",
    "算数": "math",
    "理科": "science",
    "社会": "social_studies"
}
SUBJECT_JA_MAP = {v: k for k, v in SUBJECT_MAP.items()}


def generate_safe_filename(title):
    """ページタイトルから安全なファイル名を生成する"""
    base_name = title.split('｜')[0]
    formatted_name = base_name.replace(' ', '_').replace('（', '_').replace('）', '')
    invalid_chars = r'<>:"/\|?*'
    safe_title = "".join(c if c not in invalid_chars else '_' for c in formatted_name).strip()
    return safe_title + ".pdf"

def scrape_report_urls_with_manual_help(driver, magazine_url):
    """ユーザーの手動操作を待ってからURLを収集し、新しいデータ構造で情報を保存する"""
    print(f"マガジンページを開きます: {magazine_url}")
    driver.get(magazine_url)

    print("------------------------------------------------------------------")
    input("  ブラウザですべての「もっとみる」ボタンを押し、全件表示させてから、\n  このターミナルに戻ってEnterキーを押してください...")
    print("------------------------------------------------------------------")

    print("  操作再開。ページのソースからURL候補を抽出します...")
    page_source = driver.page_source
    urls = re.findall(r'/tanabe_2024/n/([a-zA-Z0-9]+)', page_source)

    unique_urls = sorted(list(set(urls)))
    print(f"{len(unique_urls)}件のURL候補を検出しました。")

    if not unique_urls:
        return []

    # 既存のデータを読み込む
    if os.path.exists(JSON_OUTPUT_FILE):
        with open(JSON_OUTPUT_FILE, 'r', encoding='utf-8') as f:
            existing_reports = json.load(f)
        # school_nameをキーにした辞書を作成して高速アクセス
        reports_map = {report['school_name']: report for report in existing_reports}
    else:
        reports_map = {}

    # Kakasiの初期化
    kks = kakasi()
    kks.setMode("H", "a")
    kks.setMode("K", "a")
    kks.setMode("J", "a")
    conv = kks.getConverter()

    print("  - 各URLにアクセスして学校名と教科を取得し、情報を更新します...")

    processed_schools = set()

    for i, url_slug in enumerate(unique_urls):
        full_url = f"https://note.com/tanabe_2024/n/{url_slug}"
        try:
            driver.get(full_url)
            time.sleep(1)
            title = driver.title

            # タイトルから学校名と教科を抽出
            match = re.search(r'(.+?)\s+(国語|算数|理科|社会)\s+過去問分析レポート', title)
            if not match:
                match = re.search(r'(.+?)\s+算数\s+過去問分析レポート', title)
                if match:
                    school_name = match.groups()[0]
                    subject = "算数"
                else:
                    print(f"    [{i+1}/{len(unique_urls)}] スキップ (対象外タイトル): {title}")
                    continue
            else:
                school_name, subject = match.groups()

            print(f"    [{i+1}/{len(unique_urls)}] 取得: {school_name} - {subject}")

            # 情報を更新または新規作成
            if school_name not in reports_map:
                school_name_abc = conv.do(school_name.replace("中学校", ""))
                reports_map[school_name] = {
                    "school_name": school_name,
                    "school_name_abc": school_name_abc,
                    "japanese": {"url": "", "x_post": ""},
                    "math": {"url": "", "x_post": ""},
                    "science": {"url": "", "x_post": ""},
                    "social_studies": {"url": "", "x_post": ""}
                }

            subject_en = SUBJECT_MAP.get(subject)
            if subject_en:
                reports_map[school_name][subject_en]["url"] = full_url
            processed_schools.add(school_name)

        except Exception as e:
            print(f"    [{i+1}/{len(unique_urls)}] エラー発生のためスキップ: {full_url} ({e})")

    if not processed_schools:
        print("対象の記事が見つかりませんでした。")
        return list(reports_map.values()) if reports_map else []

    final_reports = list(reports_map.values())

    print(f"最終的に{len(final_reports)}件の学校情報を収集・更新しました。")
    with open(JSON_OUTPUT_FILE, 'w', encoding='utf-8') as f:
        json.dump(final_reports, f, ensure_ascii=False, indent=2)
    print(f"'{JSON_OUTPUT_FILE}' にURLリストを保存しました。")
    return final_reports

def create_pdfs(driver, reports):
    """レポートのリストを元にPDFを生成する"""
    if not reports:
        print("PDF生成対象のレポートがありません。")
        return

    print("--- PDF生成処理を開始します ---")
    subjects = ["japanese", "math", "science", "social_studies"]

    for i, report in enumerate(reports):
        school_name = report['school_name']
        print(f"[{i+1}/{len(reports)}] 学校処理中: {school_name}")

        for subject_en in subjects:
            subject_data = report.get(subject_en)
            if not subject_data or not subject_data.get("url"):
                continue

            url = subject_data["url"]
            subject_ja = SUBJECT_JA_MAP.get(subject_en, "不明")
            print(f"  - PDF生成対象: {subject_ja}")

            try:
                pdf_filename_title = f"{school_name} {subject_ja} 過去問分析レポート"
                actual_filename = generate_safe_filename(pdf_filename_title)
                pdf_path = os.path.join(OUTPUT_DIR, actual_filename)

                if os.path.exists(pdf_path):
                    print(f"    - スキップ: 既にPDFが存在します ({actual_filename})")
                    continue

                driver.get(url)
                time.sleep(2)

                print("    - PDF生成を試みます...")
                result = driver.execute_cdp_cmd(
                    "Page.printToPDF", {
                        "printBackground": True,
                        "displayHeaderFooter": True,
                        "headerTemplate": " ",
                        "footerTemplate": '<div style="font-size: 9px; width: 100%; text-align: center;"><span class="pageNumber"></span> / <span class="totalPages"></span></div>',
                        "marginBottom": 0.7,
                    })
                pdf_data = base64.b64decode(result['data'])

                with open(pdf_path, 'wb') as f:
                    f.write(pdf_data)
                print(f"    - PDFを保存しました: {actual_filename}")

            except TimeoutException:
                print(f"    - エラー: ページの読み込みがタイムアウトしました。 ({url})")
            except Exception as e:
                print(f"    - 不明なエラーが発生しました: {e} ({url})")

def create_x_posts(driver, reports, force_regenerate=False):
    """レポートのリストを元にX投稿を生成・更新する"""
    if not reports:
        print("X投稿生成対象のレポートがありません。")
        return

    if force_regenerate:
        print("--- X投稿の【強制再生成】処理を開始します ---")
    else:
        print("--- X投稿の生成処理を開始します ---")

    needs_json_update = False
    subjects = ["japanese", "math", "science", "social_studies"]

    for i, report in enumerate(reports):
        school_name = report['school_name']
        print(f"[{i+1}/{len(reports)}] 学校処理中: {school_name}")

        for subject_en in subjects:
            subject_data = report.get(subject_en)
            if not subject_data or not subject_data.get("url"):
                continue

            if not force_regenerate and subject_data.get("x_post"):
                subject_ja = SUBJECT_JA_MAP.get(subject_en, "不明")
                print(f"  - {subject_ja}: X投稿は既に存在します。スキップします。")
                continue

            url = subject_data["url"]
            subject_ja = SUBJECT_JA_MAP.get(subject_en, "不明")
            print(f"  - X投稿生成対象: {subject_ja}")

            try:
                driver.get(url)
                time.sleep(2)

                if force_regenerate:
                    print("    - Xの投稿を強制的に再生成します...")
                else:
                    print("    - Xの投稿を生成します...")

                x_post_content = generate_x_post(driver, school_name, subject_ja, url)
                subject_data["x_post"] = x_post_content
                needs_json_update = True
                print("    - 生成完了")

            except TimeoutException:
                print(f"    - エラー: ページの読み込みがタイムアウトしました。 ({url})")
            except Exception as e:
                print(f"    - 不明なエラーが発生しました: {e} ({url})")

    if needs_json_update:
        print(f"--- Xの投稿を更新したため、'{JSON_OUTPUT_FILE}' を保存します ---")
        with open(JSON_OUTPUT_FILE, 'w', encoding='utf-8') as f:
            json.dump(reports, f, ensure_ascii=False, indent=2)
        print("  - 保存完了")

def main():
    """メイン処理"""
    os.makedirs(OUTPUT_DIR, exist_ok=True)
    print(f"PDFの保存先: '{os.path.abspath(OUTPUT_DIR)}'")

    if os.path.exists(JSON_OUTPUT_FILE):
        print(f"既存のレポートファイル '{JSON_OUTPUT_FILE}' を読み込みます。")
        try:
            with open(JSON_OUTPUT_FILE, 'r', encoding='utf-8') as f:
                reports = json.load(f)
        except (json.JSONDecodeError, IOError) as e:
            print(f"エラー: '{JSON_OUTPUT_FILE}' が読み込めませんでした。({e})")
            reports = []
    else:
        print(f"'{JSON_OUTPUT_FILE}' が見つかりません。新規に作成します。")
        reports = []

    options = Options()
    if HEADLESS_MODE:
        options.add_argument("--headless")
        options.add_argument("--disable-gpu")

    driver = None
    try:
        print("\n実行したい処理を選択してください:")
        print("  1: note.comから最新の記事情報を取得・更新する (ブラウザ操作有)")
        print("  2: 既存のJSON情報からPDFを生成する (全自動)")
        print("  3: 既存のJSON情報からX投稿を生成する（未生成のみ）")
        print("  4: 既存のJSON情報からX投稿を【強制的に再生成】する")
        print("  5: 全ての処理を順番に実行する (1→2→3)")
        choice = input("番号を入力してください (デフォルト: 5): ").strip() or "5"

        if choice in ['1', '2', '3', '4', '5']:
            print("WebDriverをセットアップしています...")
            service = Service(ChromeDriverManager().install())
            driver = webdriver.Chrome(service=service, options=options)
            driver.set_page_load_timeout(PAGE_LOAD_TIMEOUT)

        if choice == '1':
            reports = scrape_report_urls_with_manual_help(driver, MAGAZINE_URL)
        elif choice == '2':
            create_pdfs(driver, reports)
        elif choice == '3':
            create_x_posts(driver, reports, force_regenerate=False)
        elif choice == '4':
            create_x_posts(driver, reports, force_regenerate=True)
        elif choice == '5':
            reports = scrape_report_urls_with_manual_help(driver, MAGAZINE_URL)
            create_pdfs(driver, reports)
            create_x_posts(driver, reports, force_regenerate=False)
        else:
            print("無効な選択です。処理を終了します。")

    finally:
        if driver:
            driver.quit()
        print("\nすべての処理が完了しました。")

if __name__ == '__main__':
    main()
